def eulerian_num(n, m):
    # Base case: Eulerian number A(n, 0) is always 1
    if m == 0:
        return 1
    # Base case: Eulerian number A(n, n) is always 0 for n > 0
    elif n == m:
        return 0
    # Recursive formula: A(n, m) = (n - m) * A(n - 1, m - 1) + (m + 1) * A(n - 1, m)
    else:
        return (n - m) * eulerian_num(n - 1, m - 1) + (m + 1) * eulerian_num(n - 1, m)

